This has been cleaned up and verified in the QC cloud using the following algorithm. Confirmed the algorithm throws the exception on current `master` and passes with this branch.

```
    public class UniverseAlgorithm : QCAlgorithm
    {
    	private int securityCount = 50;
        private int onDataCalls = 0;
        private int onSecuritiesChangedCalls = 0;
        public override void Initialize()
        {
            SetStartDate(2017, 10, 02);
            SetEndDate(2017, 10, 4);
            UniverseSettings.Resolution = Resolution.Daily;

            AddUniverse(coarse => {
                return (from c in coarse
                    orderby c.DollarVolume descending
                    select c.Symbol).Take(securityCount);
            });
        }

        public override void OnData(Slice data)
        {
            if (data.Count != securityCount)
            {
                throw new Exception("Test failed. Excepted 50 data points.");
            }
            onDataCalls++;
            Log($"OnData {data.Count} symbols at {data.Time}");
        }

        public override void OnSecuritiesChanged(SecurityChanges changes)
        {
            onSecuritiesChangedCalls++;
            Log($"Added {changes.AddedSecurities.Count}. Removed {changes.RemovedSecurities.Count}");
        }

        public override void OnEndOfAlgorithm()
        {
            Log($"{onDataCalls} OnData Calls {onSecuritiesChangedCalls} OnSecuritiesChanged Calls");
        }
    }
```
